// Types and invoke functions are generated by tauri-specta (see
// `pnpm run bindings`). TaskRun.status is a plain `String` in Rust with a
// documented closed value set, narrowed here for the UI's exhaustive checks.
/* oxlint-disable typescript/no-unsafe-type-assertion */
import { commands } from "./bindings";
import type { TaskRun as GeneratedTaskRun } from "./bindings";

export type { Binding, DeployResult, RunnerStatus } from "./bindings";

export type TaskRun = Omit<GeneratedTaskRun, "status"> & {
  status: "running" | "completed" | "failed" | "cancelled" | "interrupted";
};

export const createWorkbenchProject = (
  path: string,
  createDirectory: boolean,
  skillIds: string[],
  agent: string,
  mode: string,
) => commands.workbenchCreateProject(path, createDirectory, skillIds, agent, mode);

export const deployWorkbenchSkills = (
  projectId: string,
  skillIds: string[],
  agent: string,
  mode: string,
) => commands.workbenchDeploySkills(projectId, skillIds, agent, mode);

export const projectBindings = (projectId: string) => commands.workbenchProjectBindings(projectId);

export const startTask = (projectId: string, prompt: string, skillIds: string[]) =>
  commands.startTask(projectId, prompt, skillIds) as Promise<TaskRun>;

export const listTasks = (projectId: string) => commands.listTasks(projectId) as Promise<TaskRun[]>;

export const cancelTask = (runId: string) => commands.cancelTask(runId) as Promise<TaskRun>;

export const getTaskLog = (runId: string) => commands.getTaskLog(runId);

export const runnerStatus = () => commands.runnerStatus();
